authors = {1: "a", 2: "b", 3: "c", 4: "d", 5: "e"}
books = [(1, "t1"), (1, "t2"), (2, "t3"), (3, "t4"), (5, "t5")]

class FakeDB:
    def __init__(self):
        self.queries = 0
    def authors(self):
        self.queries += 1
        return list(authors)
    def books_for(self, author_id):
        self.queries += 1
        return [t for a, t in books if a == author_id]
    def books_for_many(self, ids):
        self.queries += 1
        out = {}
        for a, t in books:
            if a in ids:
                out.setdefault(a, []).append(t)
        return out

db = FakeDB()
result = {a: db.books_for(a) for a in db.authors()}
print("N+1 queries:", db.queries)

db = FakeDB()
ids = db.authors()
grouped = db.books_for_many(set(ids))
result2 = {a: grouped.get(a, []) for a in ids}
print("batched queries:", db.queries, "same result:", result == result2)
